from typing import Optional, Dict, Any

from web_utils import parse_content_type, content_charset, image_type


def describe_upload(content_type: str, data: bytes) -> Dict[str, Any]:
    """
    Given a request Content-Type header value and the first bytes of the body, return:
    {
      "mime": <lower-cased media type without parameters>,
      "charset": <lower-cased charset parameter or None>,
      "image": <"png", "jpeg", "gif" or None>  # from signature bytes
    }

    Parameter values may be quoted in the header.
    """
    header = content_type or ""
    mime, _params = parse_content_type(header)  # mime is already lower-cased

    # Preserve "None" when no charset is present.
    try:
        charset = content_charset(header, default=None)
    except Exception:
        # If header parsing fails unexpectedly, fall back safely.
        charset = None
    if charset is not None:
        charset = str(charset).lower()

    detected = image_type(data)  # e.g. 'png', 'jpeg', 'gif', 'bmp', 'webp', or None
    if detected not in ("png", "jpeg", "gif"):
        detected = None

    return {"mime": mime, "charset": charset, "image": detected}

import asyncio
from typing import Any, List


def run_with_deadline(coros: list, seconds: float) -> list:
    """
    Run the given coroutines concurrently and return results in input order.

    - If a coroutine does not finish within `seconds`, it is cancelled and its result
      position is set to None.
    - Works when called repeatedly in the same process.
    """
    if seconds is None:
        raise TypeError("seconds must be a float (got None)")
    if seconds < 0:
        raise ValueError("seconds must be >= 0")

    async def _runner() -> List[Any]:
        tasks = [asyncio.create_task(c) for c in coros]
        try:
            done, pending = await asyncio.wait(tasks, timeout=seconds, return_when=asyncio.ALL_COMPLETED)
            results: List[Any] = [None] * len(tasks)

            for t in done:
                idx = tasks.index(t)  # preserves order mapping; list sizes expected small
                try:
                    results[idx] = t.result()
                except asyncio.CancelledError:
                    results[idx] = None
                except Exception:
                    # If a coroutine errors, propagate like asyncio.gather would.
                    # (Unfinished ones are not relevant once we decide to fail.)
                    raise

            if pending:
                for p in pending:
                    p.cancel()
                # Ensure cancelled tasks are fully processed.
                await asyncio.gather(*pending, return_exceptions=True)

            return results
        finally:
            # Safety: ensure no tasks are left running.
            for t in tasks:
                if not t.done():
                    t.cancel()
            if tasks:
                await asyncio.gather(*tasks, return_exceptions=True)

    # No event loop is running in the caller; create a fresh one so repeated calls work.
    loop = asyncio.new_event_loop()
    try:
        asyncio.set_event_loop(loop)
        return loop.run_until_complete(_runner())
    finally:
        try:
            loop.stop()
        finally:
            asyncio.set_event_loop(None)
            loop.close()

from __future__ import annotations

from typing import Optional


def newest_compatible(versions: list[str], minimum: str) -> str | None:
    """
    Return the highest dotted release version >= minimum.

    Versions are compared numerically component-by-component:
    - "1.10" is newer than "1.9"
    - Missing components are treated as 0 (e.g. "1.2" == "1.2.0")
    - The returned value is the original string from `versions`.
    """
    def parse_dotted(v: str) -> tuple[int, ...]:
        parts = v.split(".")
        # All components must be decimal integers for this helper.
        nums: list[int] = []
        for p in parts:
            if p == "":
                raise ValueError(f"Invalid version component in {v!r}")
            try:
                nums.append(int(p, 10))
            except ValueError as e:
                raise ValueError(f"Invalid dotted release version {v!r}") from e
        return tuple(nums)

    min_key = parse_dotted(minimum)

    def ge_key(a: tuple[int, ...], b: tuple[int, ...]) -> bool:
        # Compare component-by-component, treating missing as 0.
        n = max(len(a), len(b))
        for i in range(n):
            ai = a[i] if i < len(a) else 0
            bi = b[i] if i < len(b) else 0
            if ai != bi:
                return ai > bi or (ai == bi)
        return True

    def cmp_key(a: tuple[int, ...], b: tuple[int, ...]) -> int:
        # Returns 1 if a>b, -1 if a<b, 0 if equal under padding with zeros.
        n = max(len(a), len(b))
        for i in range(n):
            ai = a[i] if i < len(a) else 0
            bi = b[i] if i < len(b) else 0
            if ai != bi:
                return 1 if ai > bi else -1
        return 0

    best: Optional[str] = None
    best_key: Optional[tuple[int, ...]] = None

    for v in versions:
        key = parse_dotted(v)
        if not ge_key(key, min_key):
            continue
        if best is None or cmp_key(key, best_key or ()) > 0:
            best = v
            best_key = key

    return best

from __future__ import annotations

from typing import Any, Dict, Optional


def _unquote(value: str) -> str:
    value = value.strip()
    if len(value) >= 2 and ((value[0] == value[-1] == '"') or (value[0] == value[-1] == "'")):
        return value[1:-1].strip()
    return value


def _parse_content_type(header: str) -> tuple[str, Dict[str, str]]:
    """
    Parse a Content-Type header into:
      - media type (lowercased, trimmed, params removed)
      - dict of parameters (lowercased keys, unquoted values)
    """
    parts = [p.strip() for p in header.split(";") if p.strip()]
    media_type = _unquote(parts[0]).lower() if parts else ""

    params: Dict[str, str] = {}
    for p in parts[1:]:
        if "=" not in p:
            continue
        k, v = p.split("=", 1)
        k = k.strip().lower()
        v = _unquote(v.strip())
        params[k] = v

    return media_type, params


def _detect_image(data: bytes) -> Optional[str]:
    # PNG signature: 89 50 4E 47 0D 0A 1A 0A
    if len(data) >= 8 and data[:8] == b"\x89PNG\r\n\x1a\n":
        return "png"

    # JPEG signature: FF D8 FF (then E0/E1/DB/etc)
    if len(data) >= 3 and data[:3] == b"\xFF\xD8\xFF":
        return "jpeg"

    # GIF: "GIF87a" or "GIF89a"
    if len(data) >= 6 and (data[:6] == b"GIF87a" or data[:6] == b"GIF89a"):
        return "gif"

    return None


def describe_upload(content_type: str, data: bytes) -> Dict[str, Any]:
    """
    Given the request's Content-Type header value and the first bytes of the body,
    return:
      {"mime": <lower-cased media type without parameters>,
       "charset": <lower-cased charset parameter or None>,
       "image": <"png", "jpeg", "gif" or None, detected from the data's signature bytes>}
    """
    mime, params = _parse_content_type(content_type or "")
    charset = params.get("charset")
    charset = charset.lower() if charset is not None else None

    image = _detect_image(data)

    return {"mime": mime, "charset": charset, "image": image}

from __future__ import annotations

import asyncio
from typing import Any, Coroutine


def run_with_deadline(coros: list[Coroutine[Any, Any, Any]], seconds: float) -> list[Any]:
    """
    Run coroutines concurrently from synchronous code, with a deadline.

    Returns results in input order. For any coroutine that does not finish
    within `seconds`, returns None for that entry and cancels it.

    This function is safe to call repeatedly in the same process.
    """
    if seconds < 0:
        seconds = 0.0

    async def _run() -> list[Any]:
        tasks = [asyncio.create_task(c) for c in coros]
        try:
            # Wait for all tasks to finish (up to the deadline).
            done, pending = await asyncio.wait(
                tasks,
                timeout=seconds,
                return_when=asyncio.ALL_COMPLETED,
            )

            results: list[Any] = [None] * len(tasks)

            # Fill in completed tasks (propagate exceptions).
            for t in done:
                idx = tasks.index(t)  # O(n^2) worst-case; acceptable for small helpers
                results[idx] = await t

            # Cancel the rest and wait for cancellation to complete.
            if pending:
                for t in pending:
                    t.cancel()
                # Await cancellation completion; swallow CancelledError,
                # but allow other exceptions to surface.
                for t in pending:
                    try:
                        await t
                    except asyncio.CancelledError:
                        pass

            return results
        finally:
            # Ensure we don't leak tasks if something unexpected happens.
            for t in tasks:
                if not t.done():
                    t.cancel()
            # Await remaining cancellations best-effort.
            for t in tasks:
                if not t.done():
                    try:
                        await t
                    except asyncio.CancelledError:
                        pass

    # No implicit event-loop creation: use asyncio.Runner (works from sync code).
    with asyncio.Runner() as runner:
        return runner.run(_run())
